import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def ph(v):
    r = v
    p = 2
    while p * p <= v:
        if v % p == 0:
            while v % p == 0:
                v //= p
            r -= r // p
        p += 1
    if v > 1:
        r -= r // v
    return r
s = 0
for idx in range(n):
    x = a[idx]
    if (x >= 2) & (ph(x) % 2 == 0):
        s += idx
print(s)

